11	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
12	pub enum ItemType {
13	    Sword,
14	    Amulet,
15	    Staff,
16	    Potion,
17	    Rune,
18	    Moonstone,
19	}
20	
21	impl ItemType {
22	    /// The MHPCO price-list row for a main item, or `None` for a component:
23	    /// components are not on the main price list, they are charged per type
24	    /// by `component_charge`.
25	    fn main_item_base_premium(self) -> Option<f64> {
26	        match self {
27	            Self::Sword => Some(100.0),
28	            Self::Amulet => Some(60.0),
29	            Self::Staff => Some(80.0),
30	            Self::Potion => Some(40.0),
31	            Self::Rune | Self::Moonstone => None,
32	        }
33	    }
34	
35	    pub fn parse(name: &str) -> Result<Self, String> {
36	        match name {
37	            "sword" => Ok(Self::Sword),
38	            "amulet" => Ok(Self::Amulet),
39	            "staff" => Ok(Self::Staff),
40	            "potion" => Ok(Self::Potion),
41	            "rune" => Ok(Self::Rune),
42	            "moonstone" => Ok(Self::Moonstone),
43	            unknown => Err(format!("the MHPCO does not insure items of type '{unknown}'")),
44	        }
45	    }
46	}
47	
48	pub struct Item {
49	    item_type: ItemType,
50	    cursed: bool,
51	    enchantment: u32,
52	}
53	
54	impl Item {
55	    pub fn new(item_type: ItemType) -> Self {
56	        Self {
57	            item_type,
58	            cursed: false,
59	            enchantment: 0,
60	        }
61	    }
62	
63	    /// The item's enchantment level, as recorded by the MHPCO.
64	    pub fn with_enchantment(mut self, enchantment: u32) -> Self {
65	        self.enchantment = enchantment;
66	        self
67	    }
68	
69	    /// A cursed item carries the MHPCO's risk surcharge.
70	    pub fn cursed(mut self) -> Self {
71	        self.cursed = true;
72	        self
73	    }
74	
75	    /// The item-specific risk surcharges this item carries, charged against the
76	    /// item's own base premium rather than the policy total. A component carries
77	    /// none: the MHPCO records no curse, enchantment or material for one, so it
78	    /// is never an affected item.
79	    fn item_surcharge(&self) -> f64 {
80	        match self.item_type.main_item_base_premium() {
81	            Some(item_base) => item_base * self.risk_surcharge_rate(),
82	            None => 0.0,
83	        }
84	    }
85	
86	    /// Highly enchanted for rating purposes. The MHPCO reads a separate, higher
87	    /// enchantment threshold when reimbursing damage, so this one is named for
88	    /// the premium it surcharges.
89	    fn is_highly_enchanted(&self) -> bool {
90	        self.enchantment >= HIGH_ENCHANTMENT_LEVEL
91	    }
92	
93	    /// Curse and high enchantment are independent risks; an item carrying both
94	    /// is surcharged for both.
95	    fn risk_surcharge_rate(&self) -> f64 {
96	        let curse = if self.cursed { CURSE_SURCHARGE } else { 0.0 };
97	        let enchantment = if self.is_highly_enchanted() {
98	            HIGH_ENCHANTMENT_SURCHARGE
99	        } else {
100	            0.0
101	        };
102	        curse + enchantment
103	    }
104	}
105	
106	const PROCESSING_FEE: u64 = 5;
107	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
108	/// Cursed items add a risk surcharge on their own base premium.
109	const CURSE_SURCHARGE: f64 = 0.50;
110	/// Highly enchanted items -- enchantment level 5 or above -- add a risk
111	/// surcharge on their own base premium.
112	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
113	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
114	/// Components -- for example runes and moonstones -- share one price-list row.
115	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
116	
117	/// Premiums are rounded up: the MHPCO's favour is the larger amount.
118	fn round_premium_in_mhpco_favour(amount: f64) -> u64 {
119	    amount.ceil() as u64
120	}
121	
122	/// Policy-wide modifiers apply to the policy base premium, the sum of all
123	/// item base premiums. Every quoted item is treated as a first insurance.
124	fn apply_policy_modifiers(_customer: &Customer, policy_base: f64) -> f64 {
125	    policy_base + policy_base * FIRST_INSURANCE_SURCHARGE
126	}
127	
128	/// A building block of exactly 3 alike components is offered at this price
129	/// instead of the per-component base premium.
130	const COMPONENT_BLOCK_SIZE: usize = 3;
131	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
132	
133	/// Alike components -- components of the very same type -- are charged as a
134	/// block when there are exactly 3 of them.
135	const COMPONENT_TYPES: [ItemType; 2] = [ItemType::Rune, ItemType::Moonstone];
136	
137	fn component_charge(alike_count: usize) -> f64 {
138	    if alike_count == COMPONENT_BLOCK_SIZE {
139	        COMPONENT_BLOCK_BASE_PREMIUM
140	    } else {
141	        alike_count as f64 * COMPONENT_BASE_PREMIUM
142	    }
143	}
144	
145	/// How many of the policy's items are alike the given component type. Alike
146	/// components are the ones charged together, so this is where the MHPCO's
147	/// reading of "alike" lives.
148	fn alike_component_count(items: &[Item], component_type: ItemType) -> usize {
149	    items
150	        .iter()
151	        .filter(|item| item.item_type == component_type)
152	        .count()
153	}
154	
155	/// Main items are charged one price-list row each, individually.
156	fn main_items_base_premium(items: &[Item]) -> f64 {
157	    items
158	        .iter()
159	        .filter_map(|item| item.item_type.main_item_base_premium())
160	        .sum()
161	}
162	
163	/// Components are charged per group of alike components, so that a group of
164	/// exactly 3 earns the block price.
165	fn component_blocks_base_premium(items: &[Item]) -> f64 {
166	    COMPONENT_TYPES
167	        .iter()
168	        .map(|component_type| component_charge(alike_component_count(items, *component_type)))
169	        .sum()
170	}
171	
172	/// The policy base premium is the sum of the items' base premiums, with alike
173	/// components charged as blocks.
174	pub fn policy_base_premium(items: &[Item]) -> f64 {
175	    main_items_base_premium(items) + component_blocks_base_premium(items)
176	}
177	
178	/// Item-specific modifiers apply to the base premium of the affected item, not
179	/// to the policy total.
180	fn item_surcharges(items: &[Item]) -> f64 {
181	    items.iter().map(Item::item_surcharge).sum()
182	}
183	
184	pub fn quote(customer: &Customer, items: &[Item]) -> u64 {
185	    let policy_base = policy_base_premium(items);
186	    let premium_before_fee =
187	        apply_policy_modifiers(customer, policy_base) + item_surcharges(items);
188	    round_premium_in_mhpco_favour(premium_before_fee) + PROCESSING_FEE
189	}
